+            if (power == Integer.MIN_VALUE) {
+                // Integer.MAX_VALUE = -(power+1)
+                return 1.0 / (FastMath.powFast(value, Integer.MAX_VALUE) * value);
+            } else {
+                return 1.0 / FastMath.powFast(value, -power);
+            }
+        }
+    }
