+                    // Add dependencies of any modules
+                    Collection<Dependency> additionalDependencies = new LinkedHashSet<>();
+                    for (Iterator<Dependency> iterator = dependencies.iterator(); iterator.hasNext();) {
+                        Dependency dependency = iterator.next();
