+                routingTableWatcher.numReplicas -= 1;
+                assertAcked(
+                    client().admin()
+                        .indices()
+                        .prepareUpdateSettings("test")
+                        .setSettings(Settings.builder().put(IndexMetadata.SETTING_NUMBER_OF_REPLICAS, routingTableWatcher.numReplicas))
+                );
+            }
