+                                "on_failure":[
+                                  {
+                                    "geoip":{
+                                      "field":"error.message"
+                                    }
+                                  }
+                                ]
+                              }
+                            }
+                        }
+                      }
+                  }
+                }
+              ]
+            }
+            """;
