+                    "on_failure":[
+                      {
+                        "foreach":{
+                          "field":"values",
+                          "processor":
+                            {
+                              "geoip":{
+                                "field":"someField"
+                              }
+                            }
+                        }
+                      }
+                    ]
+                  }
