+            nestedForeachWithOnFailureWithGeoIpProcessor,
+            onFailureWithForeachWithGeoIp
+        );
+    }
+
+    private List<String> getPipelinesWithoutGeoIpProcessors() {
+        String empty = """
+            {
+            }
+            """;
+        String noProcessors = """
+            {
+              "processors":[
+              ]
+            }
+            """;
+        String onFailureWithForeachWithSet = """
+            {
+              "processors":[
+                {
+                  "rename":{
+                    "field":"provider",
